export const CIC_NOTE =
  'Ứng dụng không tra được hồ sơ CIC của bạn, đây chỉ là hướng dẫn chung. Khoản vay còn có thể bị chuyển nhóm vì lý do khác, ví dụ khi cơ cấu lại thời hạn trả nợ.';

/** Whether this loan reaches CIC depends on the lender, and the app can only say what the licence check supports. */
export const cicScope = (licenceStatus) =>
  licenceStatus === LICENSED
    ? 'Bên cho vay này có trong danh sách cấp phép (bản demo), nên khoản vay thường được báo cáo lên CIC. Trả đúng hạn giúp giữ lịch sử tốt, trả trễ cũng sẽ bị ghi nhận.'
    : 'Chưa xác minh được bên cho vay, nên chưa biết khoản này có được báo cáo lên CIC không. Hãy hỏi họ bằng văn bản. Nếu không được báo cáo, trả đúng hạn cũng không giúp xây dựng lịch sử tín dụng, còn chi phí và rủi ro đòi nợ vẫn còn nguyên.';
